import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}
MAIN = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    names = z.namelist()

    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall(f"{MAIN}si"):
            text = "".join(t.text or "" for t in si.iter(f"{MAIN}t"))
            shared.append(text)

    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = [(s.get("name"), s.get(f"{{{NS['r']}}}id"))
              for s in wb_root.findall(f"{MAIN}sheets/{MAIN}sheet")]

    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {r.get("Id"): r.get("Target") for r in rels}

    def resolve(target):
        t = target.lstrip("/")
        if t in names:
            return t
        if "xl/" + t in names:
            return "xl/" + t
        raise KeyError(t)

    def col_to_idx(ref):
        m = re.match(r"([A-Z]+)(\d+)", ref)
        idx = 0
        for ch in m.group(1):
            idx = idx * 26 + (ord(ch) - ord("A") + 1)
        return idx - 1  # 0-based

    all_numeric = []
    for name, rid in sheets:
        root = ET.fromstring(z.read(resolve(rel_map[rid])))
        rows = []
        for row in root.findall(f".//{MAIN}sheetData/{MAIN}row"):
            cells = {}
            for c in row.findall(f"{MAIN}c"):
                ref = c.get("r")
                t = c.get("t")
                v = c.find(f"{MAIN}v")
                val = None
                if t == "s" and v is not None:
                    val = shared[int(v.text)]
                elif v is not None:
                    val = v.text
                cells[col_to_idx(ref)] = val
            rows.append(cells)
        max_col = max((max(r.keys()) for r in rows), default=-1)
        print(f"=== Sheet: {name} ===")
        for r in rows:
            print([r.get(i) for i in range(max_col + 1)])
        # numeric sum for this sheet
        s = 0.0
        for r in rows:
            for v in r.values():
                try:
                    s += float(v)
                except (TypeError, ValueError):
                    pass
        print(f"[sum of numeric cells in sheet '{name}': {s}]")
        all_numeric.append(s)
        print()
    print("GRAND TOTAL numeric cells across all sheets:", sum(all_numeric))

